from collections import defaultdict
from hashlib import sha256
import json
from pathlib import Path
import re
import sys
from vs import ivtff, split

dest=Path(sys.argv[1])
root=Path(sys.argv[2])
data=list(ivtff.parse(root/'ZL3b-n.txt'))
public=set(split.select('practice',data))
witnesses={key:{p.id:p for p in ivtff.parse(root/name)} for key,name in
           [('ZL','ZL3b-n.txt'),('IT','IT2a-n.txt'),('RF','RF1b-e.txt')]}
quota={('H','A'):2,('H','B'):1,('P','A'):2,('B','B'):2,('S','A'):1,('S','B'):1,('T','B'):1}
window=defaultdict(list)
key=lambda s: sha256(f'K-042-open-2-v1/{s}'.encode()).hexdigest()
for p in data:
    stratum=(p.section,p.language)
    if p.id in public and stratum in quota:
        qs={}
        for name,ps in witnesses.items():
            if p.id not in ps:
                break
            qs[name]={(a.id,b.id) for a,b in zip(ps[p.id].lines,ps[p.id].lines[1:])
                      if a.unit==b.unit=='P' and b.n==a.n+1 and len(a.words)>=4 and len(b.words)>=4
                      and not (a.para_end or b.para_start)}
        if len(qs)!=len(witnesses):
            continue
        candidates=sorted(set.intersection(*qs.values()),key=lambda t:key('/'.join(t)))
        if len(candidates)>=5:
            window[stratum].append((p.id,candidates))
items={}
for item in json.loads((dest/'manifest.json').read_text())['items']:
    label=item['label']['none'][0]
    m=re.match(r'^([0-9]+[rv])(?:\s|$)',label)
    if m:
        items.setdefault('f'+m.group(1),[]).append(dict(canvas=item['id'],label=label,width=item['width'],height=item['height']))
sample={}
for stratum,n in quota.items():
    for f,candidates in sorted(window[stratum],key=lambda t:key(t[0]))[:n]:
        sample[f]=dict(stratum=stratum,candidates=len(candidates),pairs=sorted(candidates[:5],key=lambda t:int(t[0].rsplit('.',1)[1])),images=items[re.match(r'^f\d+[rv]',f)[0]])
assert len(sample)==10
(dest/'freeze.json').write_text(json.dumps(sample,indent=2)+'\n')

