import argparse
from collections import Counter, defaultdict
from dataclasses import dataclass
from hashlib import sha256
import json
import math
from pathlib import Path
import random
import re

from vs import ivtff, split

GLYPHS = 'acdefgiklmnopqrsy'
SIZE = len(GLYPHS) + 1
MODES = ('first', 'middle', 'cross')
FILES = {'ZL': 'ZL3b-n.txt', 'IT': 'IT2a-n.txt', 'RF': 'RF1b-e.txt'}
MASS = 24
RESAMPLES = 4999

@dataclass(frozen=True)
class Example:
    folio: str
    ids: tuple
    factors: tuple
    tokens: tuple
    strict: bool

def leaf(folio):
    return re.match(r'f\d+', folio)[0]

def initial(word):
    return GLYPHS.index(word[0]) if word[0] in GLYPHS else SIZE - 1

def length_bin(n):
    return sum(n > upper for upper in (7, 10, 13))

def examples(pages, locators):
    out = {}
    for page in pages:
        for upper, lower in zip(page.lines, page.lines[1:]):
            if upper.unit != lower.unit or upper.unit != 'P' or upper.n + 1 != lower.n:
                continue
            if upper.para_end or lower.para_start or min(len(upper.words), len(lower.words)) < 4:
                continue
            middle = len(lower.words) // 2
            edges = (
                (lower.words[0], lower.words[1]),
                (lower.words[middle-1], lower.words[middle]),
                (upper.words[-1], lower.words[0]),
            )
            if any(ivtff.uncertain(w) for pair in edges for w in pair):
                continue
            key = (upper.id, lower.id)
            grouping = (page.section, page.language)
            lengths = (length_bin(len(upper.words)), length_bin(len(lower.words)))
            upper_tag, lower_tag = (locators[id_] for id_ in key)
            out[key] = Example(page.id, key, (*grouping, lengths[1]),
                               tuple(tuple(initial(w) for w in pair) for pair in edges),
                               upper_tag.endswith('P0') and lower_tag == '+P0')
    return out

def train(rows):
    baseline, condition, within = (defaultdict(Counter) for _ in range(3))
    for row in rows:
        strata = ((), row.factors[:2], row.factors)
        for k, (p, t) in enumerate(row.tokens):
            for group in strata:
                baseline[k, group][t] += 1
                condition[k, group, p][t] += 1
            if k != 2:
                within[None][t] += 1
                within[p][t] += 1
    return baseline, condition, within

def shrink(counts, previous, mass):
    denominator = counts.total() + mass
    return tuple((counts[i] + mass * previous[i]) / denominator for i in range(SIZE))

def probabilities(tables, example, k, p):
    baseline, condition, within = tables
    flat = (1 / SIZE,) * SIZE
    q = flat
    stages = ((), example.factors[:2], example.factors)
    for group in stages:
        q = shrink(baseline[k, group], q, MASS)
    level = q
    # The conditional model uses the finest populated training stratum with
    # adequate support for this predecessor, with a fixed backing-off rule.
    for group in reversed(stages):
        if condition[k, group, p].total() >= MASS or not group:
            level = shrink(condition[k, group, p], q, MASS)
            break
    marginal = shrink(within[None], flat, MASS)
    prepared = shrink(within[p], marginal, MASS)
    transferred = [a*b/c for a,b,c in zip(q,prepared,marginal)]
    norm = sum(transferred)
    return q, tuple(a/norm for a in transferred), level

def means(rows):
    return [sum(values) / len(rows) for values in zip(*rows)]

def interval(values):
    s = sorted(values)
    return [s[int(.025 * len(s))],s[int(.975 * len(s))]]

def summarize(tables, evaluated):
    if not evaluated:
        return {'pairs': 0}
    observed = defaultdict(list)
    profiles = defaultdict(list)
    for row in evaluated:
        columns = [[], []]
        by_mode = []
        for k, (p, t) in enumerate(row.tokens):
            scores = []
            for possible in range(SIZE):
                q, transfer, local = probabilities(tables,row,k,possible)
                scores.append((math.log(transfer[t]/q[t]),math.log(local[t]/q[t])))
            for a, series in zip(scores[p], columns):
                series.append(a)
            by_mode.append((p, scores))
        for estimator, series in enumerate(columns):
            first, mid, cross = series
            observed[row.folio].append((first,mid,cross,first-cross,mid-cross))
        profiles[row.folio].append(by_mode)
    groups = sorted(observed)
    rng = random.Random(824110)
    shuffled_rng = random.Random(824111)
    prep = [([],[]) for _ in range(2)]
    for i in range(2):
        by_page = {f: observed[f][i::2] for f in groups}
        prep[i][0].extend(means([v for f in groups for v in by_page[f]]))
        for _ in range(RESAMPLES):
            pages = rng.choices(groups,k=len(groups))
            prep[i][1].append(means([v for f in pages for v in by_page[f]]))
    draw_means = [[],[]]
    n = len(evaluated)
    for _ in range(RESAMPLES):
        scores = [[0.]*3,[0.]*3]
        for f in groups:
            for k in range(3):
                tab = [z[k] for z in profiles[f]]
                ps = [p for p,_ in tab]
                shuffled_rng.shuffle(ps)
                for (_,catalogue), p in zip(tab,ps):
                    for i in range(2):
                        scores[i][k] += catalogue[p][i]
        for i,(first,mid,cross) in enumerate(scores):
            draw_means[i].append([x/n for x in (first,mid,cross,first-cross,mid-cross)])
    results={}
    for i,name in enumerate(('transfer','separate_fit')):
        actual,boots=prep[i]
        null=list(zip(*draw_means[i]))
        q=[sum(s)/len(s) for s in null]
        results[name]=dict(gain=actual,folio_bootstrap_95=[interval(s) for s in zip(*boots)],
                           within_folio_shuffled_mean=q,excess_over_shuffle=[a-b for a,b in zip(actual,q)],
                           upper_tail=[(1+sum(v>=a-1e-12 for v in s))/(1+len(s))
                                       for a,s in zip(actual,null)])
    return dict(pairs=n,folios=len(groups),pairs_per_folio={f:len(profiles[f]) for f in groups}, **results)

def main():
    cli=argparse.ArgumentParser()
    cli.add_argument('raw',type=Path)
    cli.add_argument('sample',type=Path)
    cli.add_argument('audit',type=Path,nargs='?')
    args=cli.parse_args()
    witness={}
    sample=json.loads(args.sample.read_text())
    chosen={tuple(ab) for q in sample.values() for ab in q['pairs']}
    assert len(chosen)==50
    verified=None if args.audit is None else {
        tuple(row['pair']) for row in json.loads(args.audit.read_text()) if row['verdict']=='verified'}
    assert verified is None or verified<=chosen
    pages={n:list(ivtff.parse(args.raw/f)) for n,f in FILES.items()}
    practice=set(split.select('practice',pages['ZL']))
    eval_leaves={leaf(f) for f in practice}
    train_set={p.id for p in pages['ZL'] if leaf(p.id) not in eval_leaves}
    for name,raw in FILES.items():
        pattern=r'^<(f\d+[rv]\d*\.\d+),([^>]+)>'
        locators=dict(re.findall(pattern,(args.raw/raw).read_text(),flags=re.M))
        witness[name]=dict(train=examples([p for p in pages[name] if p.id in train_set],locators),
                           evaluation=examples([p for p in pages[name] if p.id in practice],locators))
    common=set.intersection(*(set(r['evaluation']) for r in witness.values()))
    views={'all_common_practice':common,'preregistered':common&chosen}
    if verified is not None:
        views['scan_verified']=verified&common
        views['scan_verified_ordinary_plus_P0']={p for p in views['scan_verified']
                                                if witness['ZL']['evaluation'][p].strict}
    out={'columns':[*MODES,'first-cross','middle-cross'],
         'selected':len(chosen),'scan_verified':None if verified is None else len(verified),
         'selected_ineligible_words':[list(z) for z in sorted(chosen-common)],
         'raw_sha256':{n:sha256((args.raw/f).read_bytes()).hexdigest() for n,f in FILES.items()},
         'views':{}}
    for name,v in witness.items():
        tables=train(v['train'].values())
        out['views'][name]={'training_boundary_count':len(v['train']),
                            'training_folio_count':len({x.folio for x in v['train'].values()})}
        for label,ids in views.items():
            out['views'][name][label]=summarize(tables,[v['evaluation'][p] for p in sorted(ids)])
    print(json.dumps(out,indent=2))

if __name__=='__main__':
    main()

