"""Test whether event-level gain differences imply a change in association."""
from collections import Counter
import json
import math
import random
from statistics import median
from estimate import Example, MODES, probabilities, train

def expit(x):
    return 1 / (1 + math.exp(-x))

def retain(a,b,prevalence):
    return (1-prevalence) * expit(a) + prevalence * expit(a+b)

def sample(rng,count,period,regime):
    for i in range(count):
        factors = ('H' if i%3 else 'B', 'A' if i%2 else 'B', i%4)
        events=[]
        for k in range(3):
            rate=.5 if k<2 or regime=='constant' else .25
            base, beta = -.8, 1.6
            if regime=='no_link':
                beta=0.
                base=0.
            if k==2 and regime=='shifted':
                base=-3.2
            if k==2 and regime=='reset':
                marginal=retain(-3.2,1.6,rate)
                base=math.log(marginal/(1-marginal))
                beta=0.
            p=int(rng.random()<rate)
            t=int(rng.random()<expit(base+beta*p))
            events.append((p,t))
        yield Example('page-%03d'%(i//period),(),factors,tuple(events),True)

def oracle(regime):
    ks=[]
    for k in range(3):
        rate=.5 if k<2 or regime=='constant' else .25
        base, beta = -.8,1.6
        if regime=='no_link':
            beta=0.
            base=0.
        if k==2 and regime=='shifted':
            base=-3.2
        if k==2 and regime=='reset':
            m=retain(-3.2,1.6,rate)
            base=math.log(m/(1-m))
            beta=0.
        marg=retain(base,beta,rate)
        both=[marg,1-marg]
        agg=0
        for p,weight in enumerate([1-rate,rate]):
            b=expit(base+beta*p)
            agg+=weight*sum(x * math.log(x/y) for x,y in zip([b,1-b],both))
        ks.append(dict(conditional_log_odds_ratio=beta,mutual_information=agg))
    return ks

def verify(regime, seed):
    rng=random.Random(seed)
    tables=train(sample(rng,2110,13,regime))
    eval_rows=list(sample(rng,310,5,regime))
    pool=Counter((row.folio,k,p) for row in eval_rows for k,(p,_) in enumerate(row.tokens))
    obs=[[0.]*3 for _ in range(2)]
    shf=[[0.]*3 for _ in range(2)]
    for row in eval_rows:
        for k,(p,t) in enumerate(row.tokens):
            for v in (0,1):
                q,*d=probabilities(tables,row,k,v)
                for i,probs in enumerate(d):
                    score=math.log(probs[t]/q[t])
                    obs[i][k]+=score*(v==p)/len(eval_rows)
                    shf[i][k]+=score*(pool[row.folio,k,v]/5)/len(eval_rows)
    return [{'gain':o,'above_within_page_shuffle':[a-b for a,b in zip(o,s)]} for o,s in zip(obs,shf)]

def main():
    out={}
    for regime in ('constant','shifted','reset','no_link'):
        all_results=[verify(regime,276100+i) for i in range(32)]
        status={'theoretical':oracle(regime)}
        for i,name in enumerate(('transfer','separate_fit')):
            results=[r[i] for r in all_results]
            status[name]=dict(gains_median=[median(z['gain'][k] for z in results) for k in range(3)],
                 gain_cross_below_both=sum(x['gain'][2]<min(x['gain'][:2]) for x in results),
                 excess_median=[median(z['above_within_page_shuffle'][k] for z in results) for k in range(3)],
                 excess_cross_below_both=sum(x['above_within_page_shuffle'][2]<
                                             min(x['above_within_page_shuffle'][:2]) for x in results))
        out[regime]=status
    print(json.dumps(out,indent=2))

if __name__=='__main__':
    main()
